package geoworld.runtime;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

/**
 * R8.1q acceptance: both persisted Go models must agree with Java's runtime
 * sampling at every requested point. The input is generated by the Go audit
 * from real Minecraft world dimensions and the same feature identities.
 */
public final class GeoWorldR81qPairedSamplerVerifier {
    private GeoWorldR81qPairedSamplerVerifier() {}

    public static void main(String[] args) throws Exception {
        if (args.length != 3) {
            throw new IllegalArgumentException(
                "usage: GeoWorldR81qPairedSamplerVerifier <v129.geoworld> <v130.geoworld> <go-samples.csv>"
            );
        }
        GeoWorldV1 old = GeoWorldV1.load(Path.of(args[0]));
        GeoWorldV1 next = GeoWorldV1.load(Path.of(args[1]));
        if (!"geoworld-rules-v1.1.29".equals(old.manifest().generationRulesVersion())
            || !"geoworld-rules-v1.1.30".equals(next.manifest().generationRulesVersion())) {
            throw new AssertionError("wrong persisted model rule versions");
        }
        if (old.manifest().seed() != next.manifest().seed()) {
            throw new AssertionError("cross-version model seed changed");
        }
        List<String> lines = Files.readAllLines(Path.of(args[2]));
        if (lines.isEmpty() || !lines.get(0).equals("x,z,oldGround,newGround,oldWater,newWater,oldTerrain,newTerrain")) {
            throw new AssertionError("incorrect Go sample header");
        }
        int passed = 0;
        double worstError = 0.0;
        int differingPoints = 0;
        for (int row = 1; row < lines.size(); row++) {
            if (lines.get(row).isBlank()) continue;
            String[] columns = lines.get(row).split(",", -1);
            if (columns.length != 8) {
                throw new AssertionError("unexpected CSV columns at row " + row);
            }
            double x = Double.parseDouble(columns[0]);
            double z = Double.parseDouble(columns[1]);
            double wantOld = Double.parseDouble(columns[2]);
            double wantNew = Double.parseDouble(columns[3]);
            GeoWorldV1.RuntimeSample actualOld = old.sample(x, z);
            GeoWorldV1.RuntimeSample actualNew = next.sample(x, z);
            double oldError = Math.abs(actualOld.groundHeight() - wantOld);
            double newError = Math.abs(actualNew.groundHeight() - wantNew);
            worstError = Math.max(worstError, Math.max(oldError, newError));
            if (oldError > 2e-9 || newError > 2e-9
                || !columns[4].equals(actualOld.waterKind())
                || !columns[5].equals(actualNew.waterKind())
                || !columns[6].equals(actualOld.terrainVariant())
                || !columns[7].equals(actualNew.terrainVariant())) {
                throw new AssertionError("Go/Java mismatch row=" + row
                    + " at (" + x + "," + z + ")"
                    + " oldError=" + oldError + " newError=" + newError
                    + " oldWater=" + actualOld.waterKind() + " newWater=" + actualNew.waterKind() + " oldTerrain=" + actualOld.terrainVariant() + " newTerrain=" + actualNew.terrainVariant());
            }
            if (Math.abs(wantOld - wantNew) > 0.002) differingPoints++;
            passed++;
        }
        if (passed < 500 || differingPoints < 100) {
            throw new AssertionError("insufficient sinkhole samples/change coverage: "
                + passed + " samples, " + differingPoints + " changed");
        }
        System.out.printf(
            "PASS R8.1q Go/Java v1.1.29 + v1.1.30: samples=%d different=%d worstNormError=%.12g seed=%d%n",
            passed, differingPoints, worstError, old.manifest().seed()
        );
    }
}
